import{_ as s,l as o,o as e,c as f,v as t,p as d,x as r,d as u,i,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"userfaultfd","description":"","frontmatter":{"title":"userfaultfd","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/userfaultfd.md","filePath":"cs/userfaultfd.md","lastUpdated":1789023840000}'),n={name:"cs/userfaultfd.md"};function p(h,a,m,_,E,A){const l=o("Mermaid");return e(),f("div",null,[a[1]||(a[1]=t('<h1 id="userfaultfd" tabindex="-1">userfaultfd <a class="header-anchor" href="#userfaultfd" aria-label="Permalink to &quot;userfaultfd&quot;">​</a></h1><div class="epigraph"><p>userfaultfd 把缺页从内核填页路径转到用户守护进程：进程 sleep 在 fault 上，由另一线程 ioctl 拷入内容。</p><footer>—— 据 Linux userfaultfd(2)；Criu 与 QEMU postcopy 对 uffd 的用法</footer></div><p><a href="/cs/memcg">memcg</a> 仍由内核选页。<a href="/cs/fuse">FUSE</a> 把文件操作出核。缺口是 <strong>虚存 fault 出核</strong>：热迁移后拷、懒填充、快照恢复。不是 inotify。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>UFFDIO_REGISTER</code> 把 vma 标成用户填。缺页：内核排队事件，阻塞故障线程。管理线程 <code>UFFDIO_COPY</code>/<code>ZEROPAGE</code>/<code>CONTINUE</code>。缺口：WP 模式（写保护事件）服务检查点；与 <a href="/cs/ksm">KSM</a>/THP 的组合限制；不能无限阻塞持锁路径。本课不把 CRIU 算法写完。</p><p><span class="marginnote">与 SIGSEGV 用户处理者不同：uffd 可在不改应用二进制的情况下由外部填。fork 与事件传递有规则。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>QEMU postcopy：客户机缺页 → 源机拉页 → uffd copy 进目标。对照 FUSE：一个填文件页，一个填匿名/已注册区。对照 <a href="/cs/nfs-semantics">NFS</a>：远程填的是文件协议；uffd 是本地虚存协议。</p>',8)),(e(),d(c,null,{default:r(()=>[i(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAULT%5B%22%E7%BC%BA%E9%A1%B5%22%5D%20--%3E%20Q%5B%22uffd%20%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20Q%20--%3E%20D%5B%22%E7%94%A8%E6%88%B7%E5%AE%88%E6%8A%A4%22%5D%0A%20%20D%20--%3E%20COPY%5B%22UFFDIO_COPY%22%5D%0A%20%20COPY%20--%3E%20RUN%5B%22%E6%95%85%E9%9A%9C%E7%BA%BF%E7%A8%8B%E7%BB%A7%E7%BB%AD%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[u(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>uffd 把「页内容从哪来」做成可插策略，活迁移与惰性恢复依赖它。内核仍管页表与 rmap，用户只提供字节。不要写成数据库外部页表。安全：能操作 uffd 的进程等于能改目标地址空间。</p><p>性能：每缺页往返，适合冷页，不适合热路径。</p><p>实现上：WP 模式把写保护事件交给用户，可做检查点。COPY 必须填满故障范围，否则线程继续会再 fault。fork 后 uffd 不自动监视子进程。 读法上只引用<a href="/cs/memcg">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>userfaultfd</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 minor fault continue 的全部文件映射细节。不保证与 hugetlbfs 的每组合。下一课物理内存本身可插拔：热插拔。</p><p>版本字段会变，课序钉的是机制对象「userfaultfd」，不是某一主线内核的结构体名。 后课默认：缺页可由用户态填。内存条上线/下线，下一课热插拔。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>userfaultfd 把 fault 交给用户 ioctl 填页。</li><li>用于 postcopy 迁移与惰性填充。</li><li>内存热插拔是下一课。</li><li>出处：Linux <code>userfaultfd(2)</code>；CRIU；QEMU postcopy。</li></ul>',11))])}const T=s(n,[["render",p]]);export{P as __pageData,T as default};
